exercises.solution:
def ambil_dalam(data, jalur, bawaan=None):
    sekarang = data
    for k in jalur:
        if not isinstance(sekarang, dict) or k not in sekarang:
            return bawaan
        sekarang = sekarang[k]
    return sekarang

