exercises.solution:
def pelanggan_unik(transaksi):
    hasil = {}
    for pelanggan, produk in transaksi:
        hasil.setdefault(produk, set()).add(pelanggan)
    return hasil

def beli_a_bukan_b(transaksi, a, b):
    p = pelanggan_unik(transaksi)
    return sorted(p.get(a, set()) - p.get(b, set()))

